import unittest

class Test(unittest.TestCase):
    def test_added_item_might_contain(self):
        bf = BloomFilter(100)
        bf.add('hello')
        self.assertTrue(bf.might_contain('hello'))
    def test_never_added_likely_absent(self):
        bf = BloomFilter(1000)
        bf.add('hello')
        self.assertFalse(bf.might_contain('completely_different_string_xyz'))
    def test_empty_filter(self):
        bf = BloomFilter(100)
        self.assertFalse(bf.might_contain('anything'))

if __name__ == '__main__':
    unittest.main()
